<?php namespace App\Policies; use App\Models\FoodItem; use App\Models\User; class FoodItemPolicy { public function viewAny(?User $user): bool { return true; } public function view(?User $user, FoodItem $foodItem): bool { return true; } public function create(User $user): bool { return $user->role === 'vendor' && $user->stall !== null; } public function update(User $user, FoodItem $foodItem): bool { return $user->role === 'vendor' && $foodItem->stall && $user->id === $foodItem->stall->user_id; } public function delete(User $user, FoodItem $foodItem): bool { return $user->role === 'vendor' && $foodItem->stall && $user->id === $foodItem->stall->user_id; } }